import{f as r,o as l,c as o,ah as d}from"./chunks/framework.5bt9HFMa.js";const b=JSON.parse('{"title":"02-3 进程调度","description":"","frontmatter":{},"headers":[],"relativePath":"series/操作系统/02-3进程调度.md","filePath":"series/操作系统/02-3进程调度.md","lastUpdated":1777391754000}'),i={name:"series/操作系统/02-3进程调度.md"};function a(n,t,s,e,h,g){return l(),o("div",null,t[0]||(t[0]=[d('<h1 id="_02-3-进程调度" tabindex="-1">02-3 进程调度 <a class="header-anchor" href="#_02-3-进程调度" aria-label="Permalink to &quot;02-3 进程调度&quot;">​</a></h1><h2 id="_1-调度概述" tabindex="-1">1. 调度概述 <a class="header-anchor" href="#_1-调度概述" aria-label="Permalink to &quot;1. 调度概述&quot;">​</a></h2><h3 id="_1-1-调度的原因" tabindex="-1">1.1 调度的原因 <a class="header-anchor" href="#_1-1-调度的原因" aria-label="Permalink to &quot;1.1 调度的原因&quot;">​</a></h3><p>合理地处理计算机软硬件资源，提高系统资源利用率（如 CPU 利用率）和系统吞吐量，同时保证进程的响应时间和公平性。</p><h3 id="_1-2-调度的层次" tabindex="-1">1.2 调度的层次 <a class="header-anchor" href="#_1-2-调度的层次" aria-label="Permalink to &quot;1.2 调度的层次&quot;">​</a></h3><p>操作系统中的调度分为多个层次，各层负责不同粒度的资源分配：</p><table tabindex="0"><thead><tr><th>调度层次</th><th>功能描述</th><th>发生频率</th></tr></thead><tbody><tr><td><strong>作业调度 (Job Scheduling)</strong></td><td>从后备队列中选择作业调入内存，为其创建进程。决定“哪些作业可以进入系统”。</td><td>低</td></tr><tr><td><strong>内存调度 (Memory Scheduling / 中级调度)</strong></td><td>将暂时不能运行的进程换出到外存（挂起），或从外存换入内存。用于解决内存不足问题。</td><td>中等</td></tr><tr><td><strong>进程调度 (Process Scheduling / 短程调度)</strong></td><td>从就绪队列中选择一个进程，分配 CPU 时间片。决定“哪个进程当前运行”。</td><td>高</td></tr><tr><td><strong>线程调度 (Thread Scheduling)</strong></td><td>在多线程环境中，从线程就绪队列中选择一个线程执行。</td><td>高</td></tr></tbody></table><blockquote><p><strong>注</strong>：在现代操作系统中，“进程调度”通常指短程调度，是本章的核心内容。</p></blockquote><hr><h2 id="_2-调度方式" tabindex="-1">2. 调度方式 <a class="header-anchor" href="#_2-调度方式" aria-label="Permalink to &quot;2. 调度方式&quot;">​</a></h2><p>根据是否允许中断当前正在运行的进程，调度方式分为两类：</p><table tabindex="0"><thead><tr><th>调度方式</th><th>定义</th><th>特点</th><th>适用场景</th></tr></thead><tbody><tr><td><strong>非剥夺式 (Non-preemptive)</strong></td><td>一旦进程获得 CPU，它将一直运行直到完成或主动放弃（如等待 I/O）。即使有更高优先级的进程到来，也不会被抢占。</td><td>实现简单，开销小；但响应性差，可能导致长进程阻塞短进程。</td><td>批处理系统、早期操作系统</td></tr><tr><td><strong>剥夺式 (Preemptive)</strong></td><td>当有更高优先级或更紧急的进程进入就绪队列时，可以立即中断当前运行的进程，将 CPU 分配给新进程。</td><td>响应性好，能保证重要任务及时执行；但实现复杂，需要保存/恢复上下文，开销较大。</td><td>交互式系统、实时系统</td></tr></tbody></table><hr><h2 id="_3-主要调度算法" tabindex="-1">3. 主要调度算法 <a class="header-anchor" href="#_3-主要调度算法" aria-label="Permalink to &quot;3. 主要调度算法&quot;">​</a></h2><h3 id="_3-1-先来先服务-first-come-first-served-fcfs" tabindex="-1">3.1 先来先服务 (First-Come, First-Served, FCFS) <a class="header-anchor" href="#_3-1-先来先服务-first-come-first-served-fcfs" aria-label="Permalink to &quot;3.1 先来先服务 (First-Come, First-Served, FCFS)&quot;">​</a></h3><ul><li><strong>原理</strong>：按照进程到达就绪队列的先后顺序进行调度。</li><li><strong>优点</strong>：实现简单，公平。</li><li><strong>缺点</strong>： <ul><li>平均等待时间长。</li><li>对短进程不公平（“护航效应”：长进程后跟随的短进程需长时间等待）。</li><li>不利于 I/O 密集型进程。</li></ul></li><li><strong>调度方式</strong>：非剥夺式。</li></ul><h3 id="_3-2-短作业优先-shortest-job-first-sjf" tabindex="-1">3.2 短作业优先 (Shortest Job First, SJF) <a class="header-anchor" href="#_3-2-短作业优先-shortest-job-first-sjf" aria-label="Permalink to &quot;3.2 短作业优先 (Shortest Job First, SJF)&quot;">​</a></h3><ul><li><strong>原理</strong>：总是选择预计运行时间最短的进程优先执行。</li><li><strong>优点</strong>：理论上可使平均等待时间最小化。</li><li><strong>缺点</strong>： <ul><li>需要预知进程的运行时间，实际中难以准确估计。</li><li>可能导致长作业“饥饿”（Starvation）。</li></ul></li><li><strong>调度方式</strong>：可为非剥夺式或剥夺式（SJF 的剥夺式版本称为 <strong>最短剩余时间优先 SRTF</strong>）。</li><li><strong>SRTF (Shortest Remaining Time First)</strong>：如果新到达的进程比当前运行进程的剩余时间还短，则抢占 CPU。</li></ul><h3 id="_3-3-优先级调度-priority-scheduling" tabindex="-1">3.3 优先级调度 (Priority Scheduling) <a class="header-anchor" href="#_3-3-优先级调度-priority-scheduling" aria-label="Permalink to &quot;3.3 优先级调度 (Priority Scheduling)&quot;">​</a></h3><ul><li><strong>原理</strong>：为每个进程赋予一个优先级，调度器总是选择优先级最高的进程运行。</li><li><strong>优先级类型</strong>： <ul><li><strong>静态优先级</strong>：进程创建时确定，运行期间不变。</li><li><strong>动态优先级</strong>：根据进程行为（如等待时间、I/O 使用情况）动态调整。</li></ul></li><li><strong>优点</strong>：可以区分任务的重要性。</li><li><strong>缺点</strong>： <ul><li>低优先级进程可能长期得不到调度（饥饿）。</li><li>优先级设置不当会导致系统性能下降。</li></ul></li><li><strong>调度方式</strong>：可为非剥夺式或剥夺式。</li><li><strong>防止饥饿</strong>：引入“老化 (Aging)”机制，即随等待时间增长，逐步提升进程优先级。</li></ul><h3 id="_3-4-高响应比优先-highest-response-ratio-next-hrrn" tabindex="-1">3.4 高响应比优先 (Highest Response Ratio Next, HRRN) <a class="header-anchor" href="#_3-4-高响应比优先-highest-response-ratio-next-hrrn" aria-label="Permalink to &quot;3.4 高响应比优先 (Highest Response Ratio Next, HRRN)&quot;">​</a></h3><p>HRRN（高响应比优先）调度算法的<strong>核心是计算每个就绪进程的“响应比”</strong>，然后选择<strong>响应比最高的进程</strong>执行。下面以一个<strong>具体例子</strong>说明其<strong>计算步骤与调度过程</strong>。</p><h4 id="响应比公式" tabindex="-1">响应比公式 <a class="header-anchor" href="#响应比公式" aria-label="Permalink to &quot;响应比公式&quot;">​</a></h4><p>[ \\text{响应比} = \\frac{\\text{等待时间} + \\text{服务时间}}{\\text{服务时间}} = 1 + \\frac{\\text{等待时间}}{\\text{服务时间}} ]</p><ul><li><strong>等待时间</strong> = 当前时刻 - 到达时刻（仅对已在就绪队列中的进程）</li><li><strong>服务时间</strong> = 进程总执行时间（必须已知，HRRN 仍需预知服务时间！⚠️注意：你原文说“无需预知”是常见误解，实际仍需服务时间）</li><li><strong>调度时刻</strong>：仅当<strong>当前运行进程结束</strong>时，才触发新调度（因为 HRRN 是<strong>非剥夺式</strong>）</li></ul><hr><h4 id="示例-计算-hrrn-调度过程" tabindex="-1">示例：计算 HRRN 调度过程 <a class="header-anchor" href="#示例-计算-hrrn-调度过程" aria-label="Permalink to &quot;示例：计算 HRRN 调度过程&quot;">​</a></h4><table tabindex="0"><thead><tr><th>进程</th><th>到达时刻</th><th>服务时间（执行时间）</th></tr></thead><tbody><tr><td>P1</td><td>0</td><td>6</td></tr><tr><td>P2</td><td>2</td><td>8</td></tr><tr><td>P3</td><td>4</td><td>2</td></tr><tr><td>P4</td><td>5</td><td>4</td></tr></tbody></table><blockquote><p>调度规则：非剥夺式，每次一个进程完成后，重新计算所有<strong>已到达且未完成</strong>进程的响应比，选最大者。</p></blockquote><hr><h5 id="步骤-1-t-0" tabindex="-1">步骤 1：t = 0 <a class="header-anchor" href="#步骤-1-t-0" aria-label="Permalink to &quot;步骤 1：t = 0&quot;">​</a></h5><ul><li><p>只有 P1 到达 → 执行 P1（无选择）</p></li><li><p>P1 运行至 t = 6 结束</p></li></ul><h5 id="步骤-2-t-6-p1-完成-触发调度" tabindex="-1">步骤 2：t = 6（P1 完成，触发调度） <a class="header-anchor" href="#步骤-2-t-6-p1-完成-触发调度" aria-label="Permalink to &quot;步骤 2：t = 6（P1 完成，触发调度）&quot;">​</a></h5><p>此时已到达但未运行的进程：P2 (t=2), P3 (t=4), P4 (t=5)</p><p>计算各进程<strong>等待时间</strong>和<strong>响应比</strong>：</p><ul><li>P2: 等待时间 = 6 - 2 = 4 → 响应比 = (4 + 8) / 8 = <strong>12/8 = 1.5</strong></li><li>P3: 等待时间 = 6 - 4 = 2 → 响应比 = (2 + 2) / 2 = <strong>4/2 = 2.0</strong></li><li>P4: 等待时间 = 6 - 5 = 1 → 响应比 = (1 + 4) / 4 = <strong>5/4 = 1.25</strong></li></ul><p>✅ 选择 <strong>P3</strong>（响应比最高 = 2.0） → P3 从 t=6 执行到 t=8 结束</p><h5 id="步骤-3-t-8-p3-完成-再次调度" tabindex="-1">步骤 3：t = 8（P3 完成，再次调度） <a class="header-anchor" href="#步骤-3-t-8-p3-完成-再次调度" aria-label="Permalink to &quot;步骤 3：t = 8（P3 完成，再次调度）&quot;">​</a></h5><p>剩余进程：P2, P4</p><ul><li>P2: 等待时间 = 8 - 2 = 6 → 响应比 = (6 + 8)/8 = <strong>14/8 = 1.75</strong></li><li>P4: 等待时间 = 8 - 5 = 3 → 响应比 = (3 + 4)/4 = <strong>7/4 = 1.75</strong></li></ul><p>⚠️ 响应比相同！通常按<strong>先来先服务</strong>或<strong>进程编号</strong>处理。假设选 P2（先到达） → P2 从 t=8 执行到 t=16 结束</p><h5 id="步骤-4-t-16" tabindex="-1">步骤 4：t = 16 <a class="header-anchor" href="#步骤-4-t-16" aria-label="Permalink to &quot;步骤 4：t = 16&quot;">​</a></h5><p>只剩 P4：</p><ul><li>P4 等待时间 = 16 - 5 = 11 → 响应比 = (11 + 4)/4 = 15/4 = 3.75（但只剩它了） → P4 执行，t=16 到 t=20 结束</li></ul><hr><h4 id="📊-调度结果总结" tabindex="-1">📊 调度结果总结 <a class="header-anchor" href="#📊-调度结果总结" aria-label="Permalink to &quot;📊 调度结果总结&quot;">​</a></h4><table tabindex="0"><thead><tr><th>进程</th><th>到达</th><th>服务</th><th>开始</th><th>完成</th><th>等待（开始-到达）</th><th>周转（完成-到达）</th></tr></thead><tbody><tr><td>P1</td><td>0</td><td>6</td><td>0</td><td>6</td><td>0</td><td>6</td></tr><tr><td>P3</td><td>4</td><td>2</td><td>6</td><td>8</td><td>2</td><td>4</td></tr><tr><td>P2</td><td>2</td><td>8</td><td>8</td><td>16</td><td>6</td><td>14</td></tr><tr><td>P4</td><td>5</td><td>4</td><td>16</td><td>20</td><td>11</td><td>15</td></tr></tbody></table><h3 id="_3-5-时间片轮转-round-robin-rr" tabindex="-1">3.5 时间片轮转 (Round Robin, RR) <a class="header-anchor" href="#_3-5-时间片轮转-round-robin-rr" aria-label="Permalink to &quot;3.5 时间片轮转 (Round Robin, RR)&quot;">​</a></h3><ul><li><strong>原理</strong>：为每个进程分配一个固定长度的时间片（Time Quantum）。当时间片用完，进程被剥夺 CPU，放入就绪队列末尾，等待下一轮调度。</li><li><strong>优点</strong>： <ul><li>公平性好，每个进程都能获得 CPU 时间。</li><li>响应性好，适合交互式系统。</li></ul></li><li><strong>缺点</strong>： <ul><li>如果时间片过大，退化为 FCFS；过小则上下文切换开销大。</li><li>对长进程不够友好，周转时间可能较长。</li></ul></li><li><strong>调度方式</strong>：剥夺式。</li><li><strong>关键参数</strong>：时间片大小的选择至关重要，需在响应性和开销间权衡。</li></ul><h3 id="_3-6-多级反馈队列调度-multilevel-feedback-queue-mlfq" tabindex="-1">3.6 多级反馈队列调度 (Multilevel Feedback Queue, MLFQ) <a class="header-anchor" href="#_3-6-多级反馈队列调度-multilevel-feedback-queue-mlfq" aria-label="Permalink to &quot;3.6 多级反馈队列调度 (Multilevel Feedback Queue, MLFQ)&quot;">​</a></h3><ul><li><strong>设计思想</strong>：结合了时间片轮转和优先级调度的优点，是一种自适应调度算法。其核心是“试探”：通过观察进程的行为（CPU 使用、I/O 等待）自动将其归类到不同的队列中。</li><li><strong>典型配置</strong>： <ul><li>设置多个就绪队列，优先级从高到低排列。</li><li>每个队列拥有不同的时间片大小（高优先级队列时间片小，低优先级队列时间片大）。</li><li>新进程首先进入最高优先级队列。</li></ul></li><li><strong>调度规则</strong>： <ol><li><strong>新进程</strong>进入最高优先级队列。</li><li><strong>CPU 总是优先调度最高优先级非空队列中的进程</strong>。</li><li><strong>进程在时间片内完成</strong>：结束。</li><li><strong>进程在时间片内未完成</strong>：降级到下一级队列。</li><li><strong>进程因 I/O 等待而主动放弃 CPU</strong>：返回原队列（不降级），以鼓励 I/O 密集型进程。</li><li><strong>老化机制 (Aging)</strong>：为防止低优先级队列中的进程饥饿，系统会定期将等待时间过长的进程提升到更高优先级队列。</li></ol></li></ul><div class="warning custom-block"><p class="custom-block-title">注意</p><p>当一个正在运行的进程被更高优先级进程（例如新到达的进程进入高优先级队列）抢占时，该被中断的进程会保持在其当前所在的队列中，并通常被放回该队列的末尾（或保留其剩余时间片），等待下一次调度。它不会降级，也不会回到曾经待过的更高优先级队列。</p></div><ul><li><strong>优点</strong>： <ul><li>自适应性强，能有效区分交互式进程和批处理进程。</li><li>交互式进程（频繁 I/O）能保持在高优先级队列，获得快速响应。</li><li>长作业最终也能得到执行（通过老化机制）。</li></ul></li><li><strong>缺点</strong>：实现复杂，参数（队列数、时间片大小、老化策略）配置困难。</li><li><strong>调度方式</strong>：剥夺式。</li></ul><p>平均带权周转时间 = （进程i使用的总时间 / 进程i的服务时间） 的平均值= [ta/(ta+tw)+....+tc]/n</p><hr><h2 id="_4-关键概念与对比" tabindex="-1">4. 关键概念与对比 <a class="header-anchor" href="#_4-关键概念与对比" aria-label="Permalink to &quot;4. 关键概念与对比&quot;">​</a></h2><h3 id="_4-1-饥饿-starvation" tabindex="-1">4.1 饥饿 (Starvation) <a class="header-anchor" href="#_4-1-饥饿-starvation" aria-label="Permalink to &quot;4.1 饥饿 (Starvation)&quot;">​</a></h3><p>一个就绪的进程由于调度策略的原因，长时间得不到 CPU 时间片，从而无法向前推进的现象。</p><ul><li><strong>易发生场景</strong>： <ul><li><strong>纯 SJF/SRTF</strong>：持续有短作业到达，长作业永远被延迟。</li><li><strong>优先级调度</strong>：持续有高优先级作业到达，低优先级作业永远得不到执行。</li><li><strong>MLFQ</strong>：若无老化机制，持续有高优先级作业到达，低优先级队列中的作业会饥饿。</li></ul></li><li><strong>解决方案</strong>： <ul><li><strong>老化 (Aging)</strong>：随着时间推移，增加进程的优先级。</li><li><strong>最大等待时间限制</strong>：强制将等待过久的进程提升优先级。</li></ul></li></ul><h3 id="_4-2-各调度算法对比总结" tabindex="-1">4.2 各调度算法对比总结 <a class="header-anchor" href="#_4-2-各调度算法对比总结" aria-label="Permalink to &quot;4.2 各调度算法对比总结&quot;">​</a></h3><table tabindex="0"><thead><tr><th>算法</th><th>是否需要预知时间</th><th>是否支持抢占</th><th>是否易导致饥饿</th><th>主要优点</th><th>主要缺点</th><th>适用场景</th></tr></thead><tbody><tr><td><strong>FCFS</strong></td><td>否</td><td>通常否</td><td>否</td><td>简单、公平</td><td>平均等待时间长</td><td>教学、简单系统</td></tr><tr><td><strong>SJF</strong></td><td>是</td><td>可选</td><td>是</td><td>平均等待时间理论最优</td><td>需预知时间、易致长作业饥饿</td><td>理论分析、批处理（带老化）</td></tr><tr><td><strong>SRTF</strong></td><td>是</td><td>是</td><td>是</td><td>最优响应性（对短作业）</td><td>需预知时间、易致长作业饥饿</td><td>与 SJF 类似</td></tr><tr><td><strong>优先级调度</strong></td><td>否</td><td>可选</td><td>是</td><td>可区分任务重要性</td><td>易致低优先级饥饿</td><td>实时系统、通用系统（带老化）</td></tr><tr><td><strong>HRRN</strong></td><td>否</td><td>否</td><td>否</td><td>公平兼顾长短作业</td><td>计算开销大</td><td>理论分析、特定系统</td></tr><tr><td><strong>RR</strong></td><td>否</td><td>是</td><td>否</td><td>公平、响应性好</td><td>上下文切换开销、长进程周转时间长</td><td>交互式系统、分时系统</td></tr><tr><td><strong>MLFQ</strong></td><td>否</td><td>是</td><td>否（配老化机制）</td><td>自适应、兼顾各类进程</td><td>实现复杂、参数难调</td><td>现代通用操作系统（Linux CFS）</td></tr></tbody></table><hr><h2 id="_5-现代操作系统应用" tabindex="-1">5. 现代操作系统应用 <a class="header-anchor" href="#_5-现代操作系统应用" aria-label="Permalink to &quot;5. 现代操作系统应用&quot;">​</a></h2><ul><li><strong>Linux (CFS - Completely Fair Scheduler)</strong>： <ul><li>核心思想是“完全公平”，目标是让每个进程获得相等的 CPU 时间份额。</li><li>使用红黑树管理就绪进程，按虚拟运行时间排序。</li><li>本质是 MLFQ 的高级变体，具有完善的防饥饿机制（老化）。</li></ul></li><li><strong>Windows</strong>：采用基于优先级的多级反馈队列模型，支持实时和分时任务。</li><li><strong>实时操作系统 (RTOS)</strong>：常采用固定优先级的剥夺式调度，以保证硬实时任务的截止时间。</li></ul><hr><h2 id="_6-核心要点总结" tabindex="-1">6. 核心要点总结 <a class="header-anchor" href="#_6-核心要点总结" aria-label="Permalink to &quot;6. 核心要点总结&quot;">​</a></h2><ol><li><strong>调度层次</strong>：理解作业调度、内存调度、进程调度、线程调度的区别与联系。</li><li><strong>调度方式</strong>：掌握剥夺式与非剥夺式的定义、特点及适用场景。</li><li><strong>核心算法</strong>：熟练掌握 FCFS, SJF/SRTF, 优先级调度, HRRN, RR, MLFQ 的工作原理、优缺点及调度方式。</li><li><strong>饥饿问题</strong>：理解饥饿的成因及解决方案（特别是老化机制）。</li><li><strong>MLFQ</strong>：重点掌握其多级队列、时间片递增、降级/不降级规则、老化机制等核心特性。</li><li><strong>权衡取舍</strong>：任何调度算法都是在<strong>效率 (Throughput)</strong>、<strong>响应性 (Responsiveness)</strong>、<strong>公平性 (Fairness)</strong> 和<strong>实现复杂度</strong>之间进行权衡。</li></ol><p>参考阅读：<a href="./../../posts/操作系统调度的机制.html">操作系统调度的机制</a></p>',68)]))}const c=r(i,[["render",a]]);export{b as __pageData,c as default};
